comparisonTable.pptxRendererCode:
function(pptx, slideNum, totalSlides) {
  const slide = pptx.addSlide();
  const c = {main:'111111',secondary:'222222',red:'A32020',maroon:'8E1E1E',zone1:'F7F9FB',meta:'4A4F57',border:'E6E9EE'};
  slide.addText("[Title]", {x:0.48, y:0.42, w:12.36, h:0.8, fontFace:'Georgia', fontSize:28, color:c.main, valign:'top'});
  slide.addText("[Subtitle]", {x:0.48, y:1.40, w:12.36, h:0.4, fontFace:'Arial', fontSize:18, color:c.red, bold:true});
  const headers = ['Criteria','[Option A]','[Option B]','[Option C]'];
  const rows = [['[Criterion 1]','[Score]','[Score]','[Score]'],['[Criterion 2]','[Score]','[Score]','[Score]'],['[Criterion 3]','[Score]','[Score]','[Score]'],['[Criterion 4]','[Score]','[Score]','[Score]']];
  const tX=0.48, tW=12.36, colW=tW/4, rH=0.7;
  headers.forEach((h,i) => {
    slide.addShape('rect',{x:tX+i*colW,y:1.95,w:colW,h:0.5,fill:{color:c.maroon}});
    slide.addText(h,{x:tX+i*colW,y:1.95,w:colW,h:0.5,fontFace:'Arial',fontSize:11,color:'FFFFFF',bold:true,align:'center',valign:'middle'});
  });
  rows.forEach((row,ri) => {
    const y=2.5+ri*rH;
