  var totalW = bars.length * barW + (bars.length - 1) * 0.15;
  var startX = 4.8 + (7.8 - totalW) / 2;
  bars.forEach(function(bar, bi) {
    var bx = startX + bi * (barW + 0.15);
    var barH = (parseFloat(bar.value) / maxVal) * 3.5;
    var by = 2.0 + (3.8 - barH);
    slide.addShape(pptx.shapes.RECTANGLE, { x: bx, y: by, w: barW, h: barH, fill: { color: bi === 0 ? 'A32020' : '8E1E1E' } });
    slide.addText(String(bar.value), { x: bx, y: by - 0.3, w: barW, h: 0.25, fontSize: 9, fontFace: 'Arial', color: '111111', bold: true, align: 'center' });
    slide.addText(bar.label || '', { x: bx - 0.1, y: 5.9, w: barW + 0.2, h: 0.5, fontSize: 8, fontFace: 'Arial', color: '4A4F57', align: 'center', valign: 'top' });
  });
  slide.addText(slideData.company || '', { x: 0.48, y: 7.05, w: 5, h: 0.3, fontSize: 8, fontFace: 'Arial', color: '4A4F57' });
  slide.addText(slideNum + ' / ' + totalSlides, { x: 11.5, y: 7.05, w: 1.5, h: 0.3, fontSize: 8, fontFace: 'Arial', color: '4A4F57', align: 'right' });
}

scorecard.pptxRendererCode:
function(pptx, slideData, slideNum, totalSlides) {
  var slide = pptx.addSlide();
  slide.background = { color: 'FFFFFF' };
  slide.addText(slideData.title || 'Scorecard', { x: 0.48, y: 0.42, w: 11.5, h: 0.55, fontSize: 24, fontFace: 'Georgia', color: '111111', bold: true });
  slide.addText(slideData.subtitle || '', { x: 0.48, y: 1.05, w: 11.5, h: 0.35, fontSize: 13, fontFace: 'Arial', color: '4A4F57' });
  var criteria = slideData.criteria || ['Criterion 1','Criterion 2','Criterion 3','Criterion 4'];
  var rows = slideData.rows || slideData.items || [];
  var headerRow = [{ text: 'Entity', options: { bold: true, fontSize: 9, color: 'FFFFFF', fill: { color: '8E1E1E' } } }];
  criteria.forEach(function(c) { headerRow.push({ text: c, options: { bold: true, fontSize: 9, color: 'FFFFFF', fill: { color: '8E1E1E' }, align: 'center' } }); });
  headerRow.push({ text: 'Overall', options: { bold: true, fontSize: 9, color: 'FFFFFF', fill: { color: '8E1E1E' }, align: 'center' } });
  var tableRows = [headerRow];
  rows.forEach(function(row) {
    var cells = [{ text: row.entity || row.name || '', options: { fontSize: 9, color: '111111', bold: true } }];
    var scores = row.scores || [];
    scores.forEach(function(s) {
      var ragColors = { Strong: 'C5E1A5', green: 'C5E1A5', Moderate: 'FFF9C4', amber: 'FFF9C4', Weak: 'FFCDD2', red: 'FFCDD2' };
      var bg = ragColors[s] || 'F7F9FB';
      cells.push({ text: s, options: { fontSize: 9, color: '111111', fill: { color: bg }, align: 'center', bold: true } });
    });
    cells.push({ text: row.overall || '', options: { fontSize: 10, color: '111111', bold: true, align: 'center', fill: { color: 'F7F9FB' } } });
    tableRows.push(cells);
  });
  var colW = [2.5];
  criteria.forEach(function() { colW.push((12.36 - 2.5 - 1.5) / criteria.length); });
  colW.push(1.5);
  slide.addTable(tableRows, { x: 0.48, y: 1.90, w: 12.36, colW: colW, rowH: 0.4, border: { pt: 0.5, color: 'E6E9EE' }, autoPage: false });
  slide.addText(slideData.company || '', { x: 0.48, y: 7.05, w: 5, h: 0.3, fontSize: 8, fontFace: 'Arial', color: '4A4F57' });
  slide.addText(slideNum + ' / ' + totalSlides, { x: 11.5, y: 7.05, w: 1.5, h: 0.3, fontSize: 8, fontFace: 'Arial', color: '4A4F57', align: 'right' });
}

metricDashboard.pptxRendererCode:
function(pptx, slideNum, totalSlides) {
  const slide = pptx.addSlide();
  const c = {main:'111111',secondary:'222222',red:'A32020',maroon:'8E1E1E',zone1:'F7F9FB',meta:'4A4F57',border:'E6E9EE',green:'2E7D32',redNeg:'C62828'};
  slide.addText("[Main heading]", {x:0.48, y:0.42, w:12.36, h:0.8, fontFace:'Georgia', fontSize:28, color:c.main, valign:'top'});
  slide.addText("[Subtitle]", {x:0.48, y:1.40, w:12.36, h:0.4, fontFace:'Arial', fontSize:18, color:c.red, bold:true});
  const metrics = [
    {icon:'[Icon]', value:'[Value 1]', label:'[Label 1]', trend:'+12%', trendColor:c.green},
    {icon:'[Icon]', value:'[Value 2]', label:'[Label 2]', trend:'+8%', trendColor:c.green},
    {icon:'[Icon]', value:'[Value 3]', label:'[Label 3]', trend:'-3%', trendColor:c.redNeg},
    {icon:'[Icon]', value:'[Value 4]', label:'[Label 4]', trend:'+15%', trendColor:c.green},
    {icon:'[Icon]', value:'[Value 5]', label:'[Label 5]', trend:'0%', trendColor:c.meta},
    {icon:'[Icon]', value:'[Value 6]', label:'[Label 6]', trend:'+5%', trendColor:c.green}
  ];
  const startX = 0.48, startY = 1.9, cellW = 4.0, cellH = 2.35, gapX = 0.18, gapY = 0.18;
  metrics.forEach((m, i) => {
    const col = i % 3, row = Math.floor(i / 3);
    const x = startX + col * (cellW + gapX), y = startY + row * (cellH + gapY);
    slide.addShape('roundRect', {x:x, y:y, w:cellW, h:cellH, fill:{color:c.zone1}, line:{color:c.border, width:1}, rectRadius:0.05});
    slide.addShape('rect', {x:x, y:y, w:cellW, h:0.06, fill:{color:c.maroon}});
    slide.addText(m.icon, {x:x + 0.2, y:y + 0.2, w:0.5, h:0.5, fontSize:18, color:c.maroon, align:'center'});
    slide.addText(m.value, {x:x + 0.2, y:y + 0.7, w:cellW - 0.4, h:0.7, fontFace:'Georgia', fontSize:32, color:c.maroon, bold:true});
    slide.addText(m.label, {x:x + 0.2, y:y + 1.4, w:cellW - 0.4, h:0.4, fontFace:'Arial', fontSize:12, color:c.meta});
    slide.addText(m.trend, {x:x + 0.2, y:y + 1.85, w:cellW - 0.4, h:0.35, fontFace:'Arial', fontSize:11, color:m.trendColor, bold:true});
  });
  slide.addText('[Company]', {x:0.48, y:7.05, w:2, h:0.25, fontFace:'Arial', fontSize:10, color:c.meta});
  slide.addText(slideNum + ' / ' + totalSlides, {x:11.5, y:7.05, w:1.3, h:0.25, fontFace:'Arial', fontSize:10, color:c.meta, align:'right'});
}
